* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  height: 100%;
}

body {
  background: var(--bg-canvas);
  color: var(--text-secondary);
  font: var(--base-font-size) var(--font-body);
  line-height: 1.6;
  padding: 3rem 2rem 5rem;
  display: flex;
  justify-content: center;
}

.app-container {
  width: 100%;
  max-width: 1400px;
  display: flex;
  flex-direction: column;
  gap: var(--gap-xl);
}

/* ========================================================================
   HEADER & NAVIGATION
   ======================================================================== */

.header {
  display: flex;
  flex-direction: column;
  gap: var(--gap-md);
  padding-bottom: var(--gap-lg);
  border-bottom: 1px solid var(--border-light);
}

.header-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--gap-md);
  flex-wrap: wrap;
}

h1 {
  font: 700 2.5rem var(--font-display);
  color: var(--text-primary);
  margin: 0;
  display: flex;
  align-items: center;
  gap: 1rem;
}

.badge {
  font: 600 0.85rem var(--font-mono);
  color: var(--accent);
  background: var(--accent-bg);
  border: 1px solid var(--accent);
  padding: 0.5rem 0.9rem;
  border-radius: var(--radius-sm);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.header-subtitle {
  font: 16px var(--font-body);
  color: var(--text-tertiary);
  max-width: 600px;
}

.header-actions {
  display: flex;
  gap: var(--gap-sm);
  flex-wrap: wrap;
}

/* ========================================================================
   BUTTONS & CONTROLS
   ======================================================================== */

button {
  font: inherit;
  cursor: pointer;
  border: none;
  outline: none;
  transition: all 0.15s ease;
  border-radius: var(--radius-md);
}

.btn {
  height: 52px;
  padding: 0 1.5rem;
  font-weight: 600;
  font-size: 16px;
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  color: var(--text-secondary);
}

.btn:hover {
  background: var(--bg-card-hover);
  border-color: var(--border-mid);
  color: var(--text-primary);
}

.btn.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #0a0908;
  font-weight: 700;
}

.btn.primary:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.btn.small {
  height: 42px;
  padding: 0 1rem;
  font-size: 14px;
}

.btn.icon-only {
  width: 52px;
  padding: 0;
  justify-content: center;
}

/* Navigation tabs */
.nav-tabs {
  display: flex;
  gap: var(--gap-xs);
  flex-wrap: wrap;
  background: var(--bg-card);
  border: 1px solid var(--border-light);
  padding: var(--gap-sm);
  border-radius: var(--radius-md);
}

