       ======================================================================== */

    .filter-bar {
      display: flex;
      gap: var(--gap-sm);
      flex-wrap: wrap;
      margin-bottom: var(--gap-md);
    }

    .filter-btn {
      padding: 0.5rem 1rem;
      font: 600 13px var(--font-body);
      background: var(--bg-card);
      border: 1px solid var(--border-light);
      border-radius: var(--radius-sm);
