}

function copyCode() {
  const text = document.getElementById('code-content').textContent;
  navigator.clipboard.writeText(text).then(() => {
    showToast('Copied to clipboard!');
  });
}

function saveTable() {
  localStorage.setItem('project_entry_schemas', JSON.stringify(tables));
  showToast('Saved to local storage');
}

function syncSqlite() {
  showToast('SQLite sync (frontend only in standalone mode)');
}

function toggleTheme() {
  const current = document.documentElement.getAttribute('data-theme') || 'system';
  const next = current === 'dark' ? 'light' : current === 'light' ? 'system' : 'dark';
  if (next === 'system') {
    document.documentElement.removeAttribute('data-theme');
  } else {
    document.documentElement.setAttribute('data-theme', next);
  }
}

function showToast(msg) {
  const toast = document.getElementById('toast');
  toast.textContent = msg;
  toast.classList.add('show');
  setTimeout(() => toast.classList.remove('show'), 2400);
}

/* ========================================================================
   [CHANGED SECTION]: POINTER DRAG-AND-DROP ENGINE WITH REAL-TIME FLIP PHYSICS
   Replaced rigid HTML5 DnD (dragstart/dragover/drop) with:
   1. PointerEvents (PointerDown/Move/Up) for 60fps responsiveness.
   2. FLIP (First-Last-Invert-Play) animations on adjacent tokens when reordering.
   3. 2D Coordinate bounding box detection for flex-wrapped items.
   ======================================================================== */

function renderColumnOrderDashboard() {
  if (!tables[activeTable]) return;
  const table = tables[activeTable];
  const dashboard = document.getElementById('dashboard-tokens');
  if (!dashboard) return;

  dashboard.innerHTML = table.columns.map((col, idx) => {
    const type = FIELD_TYPES[col.type];
    return `
      <div class="column-token" data-index="${idx}">
        <span class="token-drag-handle">⋮⋮</span>
        <span class="token-icon">${type.icon}</span>
        <span class="token-name">${col.name}</span>
        <span class="token-type">${type.title}</span>
      </div>
    `;
  }).join('');

  // Bind pointer events directly to each token
  dashboard.querySelectorAll('.column-token').forEach(token => {
    token.addEventListener('pointerdown', handleTokenPointerDown);
  });
}

let activeDrag = null;

function handleTokenPointerDown(e) {
  // Allow only primary mouse button or single touch
  if (e.button !== 0) return;

  const token = e.currentTarget;
  const dashboard = document.getElementById('dashboard-tokens');
  const fromIndex = Number(token.dataset.index);
  const rect = token.getBoundingClientRect();

  // Capture pointer so dragging persists outside the element/browser window
  token.setPointerCapture(e.pointerId);

  // Create landing placeholder slot
  const placeholder = document.createElement('div');
  placeholder.className = 'token-placeholder';
  placeholder.style.width = `${rect.width}px`;
  placeholder.style.height = `${rect.height}px`;

  // Calculate cursor offset relative to token top-left
  const offsetX = e.clientX - rect.left;
  const offsetY = e.clientY - rect.top;

  activeDrag = {
    token,
    dashboard,
    fromIndex,
    placeholder,
    offsetX,
    offsetY,
    initialRect: rect,
    isDragging: false,
    startX: e.clientX,
    startY: e.clientY
  };

  const onPointerMove = (moveEvent) => {
    if (!activeDrag) return;

    const deltaDist = Math.hypot(moveEvent.clientX - activeDrag.startX, moveEvent.clientY - activeDrag.startY);

    // Prevent micro-jitter on normal clicks: activate drag only after 3px threshold
    if (!activeDrag.isDragging && deltaDist > 3) {
      activeDrag.isDragging = true;

      // Insert placeholder at token's current DOM index
      token.parentNode.insertBefore(placeholder, token);

      // Elevate dragged token to a floating surface
      token.classList.add('is-dragging');
      token.style.width = `${rect.width}px`;
      token.style.height = `${rect.height}px`;
      token.style.left = `${moveEvent.clientX - activeDrag.offsetX}px`;
      token.style.top = `${moveEvent.clientY - activeDrag.offsetY}px`;
    }

    if (activeDrag.isDragging) {
      // Track cursor position instantaneously (no CSS transition lag)
      token.style.left = `${moveEvent.clientX - activeDrag.offsetX}px`;
      token.style.top = `${moveEvent.clientY - activeDrag.offsetY}px`;

      // Re-evaluate target insertion position with FLIP
      updateTokenPlacementFLIP(moveEvent.clientX, moveEvent.clientY);
    }
  };

  const onPointerUp = () => {
    if (!activeDrag) return;

    window.removeEventListener('pointermove', onPointerMove);
    window.removeEventListener('pointerup', onPointerUp);

    try {
      token.releasePointerCapture(e.pointerId);
    } catch (_) {}

    if (!activeDrag.isDragging) {
      activeDrag = null;
      return;
    }

    // Animate floating token to its placeholder target slot
    const targetRect = placeholder.getBoundingClientRect();
    const currentLeft = parseFloat(token.style.left);
    const currentTop = parseFloat(token.style.top);
    const deltaX = targetRect.left - currentLeft;
    const deltaY = targetRect.top - currentTop;

    token.style.transition = 'transform 0.22s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.22s ease';
    token.style.transform = `translate(${deltaX}px, ${deltaY}px)`;
    token.style.boxShadow = 'none';

    setTimeout(() => {
      // Calculate new landing index
      const children = [...dashboard.children].filter(c => c !== token);
      const toIndex = children.indexOf(placeholder);

      // Clean up inline styles
      token.classList.remove('is-dragging');
      token.style.position = '';
      token.style.left = '';
      token.style.top = '';
      token.style.width = '';
      token.style.height = '';
      token.style.transform = '';
      token.style.transition = '';
      token.style.boxShadow = '';

      if (placeholder.parentNode) {
        placeholder.parentNode.removeChild(placeholder);
      }

      if (toIndex !== -1 && toIndex !== activeDrag.fromIndex) {
        // Apply reorder to data model
        const cols = tables[activeTable].columns;
        const [movedCol] = cols.splice(activeDrag.fromIndex, 1);
        cols.splice(toIndex, 0, movedCol);

        remapCollapsedIndices(activeDrag.fromIndex, toIndex);
        renderColumns();
        updateInspector();
      }

      activeDrag = null;
    }, 220);
  };

  window.addEventListener('pointermove', onPointerMove, { passive: true });
  window.addEventListener('pointerup', onPointerUp);
}

