    /**
     * Finds insertion position and executes FLIP animation on siblings
     */
    function updateTokenPlacementFLIP(pointerX, pointerY) {
      const { dashboard, token, placeholder } = activeDrag;
      const elements = [...dashboard.querySelectorAll('.column-token:not(.is-dragging)')];

      // Find the closest slot using 2D geometry (handles flex-wrap rows seamlessly)
      let targetChild = null;

      for (const el of elements) {
        const box = el.getBoundingClientRect();
        // If pointer is above element row
        if (pointerY < box.top - 4) {
          targetChild = el;
          break;
        }
        // If pointer is within the row and to the left of the item center
        if (pointerY <= box.bottom + 4 && pointerX < box.left + box.width / 2) {
          targetChild = el;
          break;
        }
      }

      // Check if placeholder placement actually changed
      const currentNext = placeholder.nextElementSibling === token ? token.nextElementSibling : placeholder.nextElementSibling;
      if (currentNext === targetChild) return;

      // 1. FIRST: Record bounding box of all siblings prior to layout shift
      const firstPositions = new Map();
      elements.forEach(el => firstPositions.set(el, el.getBoundingClientRect()));

      // 2. DOM Shift: Reposition placeholder
      if (targetChild) {
        dashboard.insertBefore(placeholder, targetChild);
      } else {
        dashboard.appendChild(placeholder);
      }

      // 3. LAST, INVERT & PLAY: Smoothly transition each shifted token
      elements.forEach(el => {
        const first = firstPositions.get(el);
        const last = el.getBoundingClientRect();
        const dx = first.left - last.left;
        const dy = first.top - last.top;

        if (dx !== 0 || dy !== 0) {
          // Invert: snap immediately to previous visual coordinate
          el.style.transition = 'none';
          el.style.transform = `translate(${dx}px, ${dy}px)`;
          el.offsetHeight; // Force browser reflow

          // Play: glide gracefully into new slot
          el.style.transition = 'transform 0.26s cubic-bezier(0.2, 0, 0, 1)';
          el.style.transform = '';
        }
      });
    }
    /* ========================================================================
       [END OF CHANGED SECTION]
       ======================================================================== */

    init();
  </script>
</body>

</html>

