/* ========================================================================
   TOOLBAR (below header, above table) — two compact rows
   ======================================================================== */
.toolbar {
  flex-shrink: 0;
  background: var(--bg-canvas);
  border-bottom: 1px solid var(--border-table);
  display: flex;
  flex-direction: column;
}

/* Row 1: Filter bar */
.toolbar-row {
  padding: 0.45rem 1.25rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  border-bottom: 1px solid var(--border-table);
}

.toolbar-row:last-child { border-bottom: none; }

/* Row 2: Order strip — single horizontal scrollable line */
.toolbar-order-row {
  padding: 0.35rem 1.25rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  overflow-x: auto;
  scrollbar-width: none;
}

.toolbar-order-row::-webkit-scrollbar { display: none; }

.toolbar-label {
  font: 600 10px var(--font-mono);
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.07em;
  white-space: nowrap;
  flex-shrink: 0;
}

.toolbar-divider {
  width: 1px;
  height: 14px;
  background: var(--border-light);
  flex-shrink: 0;
}

